import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.D2VFKYIt.js";const m=JSON.parse('{"title":"What a migration creates","description":"","frontmatter":{"order":10},"headers":[],"relativePath":"migrations/generated-schema.md","filePath":"migrations/generated-schema.md"}'),r={name:"migrations/generated-schema.md"};function i(n,t,h,s,c,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="what-a-migration-creates" tabindex="-1">What a migration creates <a class="header-anchor" href="#what-a-migration-creates" aria-label="Permalink to &quot;What a migration creates&quot;">​</a></h1><p>For every temporal entity, the migration that first includes it creates a history table, two indexes on it and, with the trigger writer, a trigger. Later migrations keep them in step with the entity; see <a href="/hindsight-efcore/1.1/migrations/schema-evolution">Evolving a temporal entity</a>.</p><h2 id="the-history-table" tabindex="-1">The history table <a class="header-anchor" href="#the-history-table" aria-label="Permalink to &quot;The history table&quot;">​</a></h2><p>Named <code>&lt;main table&gt;_history</code> in the main table&#39;s schema, unless you <a href="/hindsight-efcore/1.1/configuration/temporal-entities#customizing">choose another name</a>.</p><table tabindex="0"><thead><tr><th>column</th><th>type</th><th></th></tr></thead><tbody><tr><td><code>history_id</code></td><td><code>bigint generated always as identity</code></td><td>the history table&#39;s own primary key</td></tr><tr><td>every versioned column</td><td>as in the main table, but nullable</td><td><a href="/hindsight-efcore/1.1/configuration/temporal-entities#excluding-properties">excluded</a> properties are left out</td></tr><tr><td><code>valid_from</code></td><td><code>timestamptz not null</code></td><td>start of the version&#39;s period, included</td></tr><tr><td><code>valid_to</code></td><td><code>timestamptz not null</code></td><td>end of the period, excluded; <code>&#39;infinity&#39;</code> for the current version</td></tr><tr><td><code>operation</code></td><td><code>smallint</code></td><td><code>1</code> insert, <code>2</code> update, <code>3</code> delete</td></tr><tr><td><code>changed_by</code>, <code>changed_by_name</code>, <code>correlation_id</code>, <code>reason</code></td><td><code>text null</code></td><td>the <a href="/hindsight-efcore/1.1/writing/change-context">change context</a></td></tr><tr><td><code>extra</code></td><td><code>jsonb null</code></td><td>the change context&#39;s JSON extras</td></tr></tbody></table><p>The history table has <strong>no foreign keys</strong> back to the main table, because a deleted row&#39;s history must outlive it, and <strong>none of the main table&#39;s <code>NOT NULL</code>, unique or check constraints</strong>, because a unique index on a history table breaks on the second edit of a row. Don&#39;t add them by hand.</p><h2 id="indexes" tabindex="-1">Indexes <a class="header-anchor" href="#indexes" aria-label="Permalink to &quot;Indexes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>index</th><th>definition</th><th>serves</th></tr></thead><tbody><tr><td><code>ix_&lt;history_table&gt;_version</code></td><td>btree on <code>(&lt;primary key columns&gt;, valid_from desc)</code></td><td>historical queries filtered by the entity&#39;s key</td></tr><tr><td><code>ix_&lt;history_table&gt;_period</code></td><td><code>gist (tstzrange(valid_from, valid_to))</code></td><td>point-in-time queries that are not filtered by key</td></tr></tbody></table><p>The period index needs no extension: range types have a GiST operator class in PostgreSQL core. Both indexes are created once, with the table, and never changed by a later migration. History tables created before 1.1 lack the period index; see <a href="/hindsight-efcore/1.1/migrations/existing-tables#backfilling-the-period-range-index">Backfilling the period-range index</a>.</p><h2 id="the-trigger" tabindex="-1">The trigger <a class="header-anchor" href="#the-trigger" aria-label="Permalink to &quot;The trigger&quot;">​</a></h2><p>With <code>HistoryWriter.Trigger</code>, the same migration also creates the <code>&lt;history_table&gt;_write()</code> function and the <code>&lt;history_table&gt;_trg</code> trigger on the main table. See <a href="/hindsight-efcore/1.1/writing/trigger">Trigger writer</a>.</p><h2 id="where-the-ddl-comes-from" tabindex="-1">Where the DDL comes from <a class="header-anchor" href="#where-the-ddl-comes-from" aria-label="Permalink to &quot;Where the DDL comes from&quot;">​</a></h2><table tabindex="0"><thead><tr><th>object</th><th>in the migration&#39;s C#</th><th>added when the migration becomes SQL</th></tr></thead><tbody><tr><td>history table, version index</td><td>✅ they are part of the EF Core model</td><td></td></tr><tr><td>period index</td><td></td><td>✅</td></tr><tr><td>trigger function and trigger</td><td></td><td>✅</td></tr></tbody></table><p>Hindsight adds the SQL-only objects when EF Core turns a migration into SQL, which is what <code>dotnet ef database update</code>, <code>dotnet ef migrations script</code>, migration bundles and <code>Database.Migrate()</code> all do. Two consequences:</p><ul><li>Review a migration with <code>dotnet ef migrations script</code>, not only by reading its C# file.</li><li>The context that <strong>applies</strong> migrations must be configured with <code>UseHindsight()</code> and the same <code>UseHistoryWriter(...)</code> as your application. For the <code>dotnet ef</code> tools that is your design-time context: the one your <code>IDesignTimeDbContextFactory</code> creates, or your application&#39;s own registration.</li></ul><h2 id="generated-names" tabindex="-1">Generated names <a class="header-anchor" href="#generated-names" aria-label="Permalink to &quot;Generated names&quot;">​</a></h2><table tabindex="0"><thead><tr><th>object</th><th>name</th></tr></thead><tbody><tr><td>history table</td><td><code>&lt;main table&gt;_history</code></td></tr><tr><td>version index</td><td><code>ix_&lt;history_table&gt;_version</code></td></tr><tr><td>period index</td><td><code>ix_&lt;history_table&gt;_period</code></td></tr><tr><td>trigger function</td><td><code>&lt;history_table&gt;_write()</code></td></tr><tr><td>trigger</td><td><code>&lt;history_table&gt;_trg</code></td></tr></tbody></table><p>Every name must fit PostgreSQL&#39;s 63-byte identifier limit; Hindsight checks that when it builds the model. See <a href="/hindsight-efcore/1.1/configuration/model-validation">Model validation</a>.</p>',18)])])}const b=e(r,[["render",i]]);export{m as __pageData,b as default};
